:root{--bg:#0c0e12;--panel:#14171d;--panel2:#191d24;--line:#262b34;--text:#e8e6df;--muted:#9a978c;--dim:#6f6d66;--amber:#e8c478;--green:#4caf7d;--orange:#d9a441;--grey:#6b6f76;--red:#c96a5a;--blue:#7aa7c9}
*{box-sizing:border-box}
body{background:var(--bg);color:var(--text);font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;margin:0;font-size:14px;line-height:1.45}
.skip{position:absolute;left:-9999px}
a{color:var(--amber)}
.wrap{max-width:1180px;margin:0 auto;padding:20px 20px 40px}
header h1{font-size:28px;margin:0 0 4px;letter-spacing:.2px}
header h1 .dot{color:var(--amber)}
.sub{color:var(--muted);margin:0 0 14px;max-width:820px}
.kpi{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 16px}
.kpi span{background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:6px 10px;font-size:13px}
.kpi b{color:var(--amber);font-weight:650}
.tabs{display:flex;gap:6px;margin:0 0 16px;border-bottom:1px solid var(--line);padding-bottom:0}
.tabs button{background:none;border:none;border-bottom:2px solid transparent;color:var(--muted);font:inherit;font-size:14px;padding:8px 12px;cursor:pointer}
.tabs button.on{color:var(--text);border-bottom-color:var(--amber)}
.tabs button:hover{color:var(--text)}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:16px 18px;margin:0 0 16px}
.panel h2{font-size:16px;margin:0 0 8px}
.panel h3{font-size:14px;margin:16px 0 6px;color:var(--amber)}
.panel p{margin:6px 0;color:var(--muted)}
.panel p b,.panel td b{color:var(--text)}
.muted{color:var(--muted)}
.small{font-size:12.5px;color:var(--muted)}
.num{font-variant-numeric:tabular-nums;text-align:right;white-space:nowrap}
.filters{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:0 0 12px}
.filters input,.filters select{background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:6px;padding:7px 9px;font:inherit;font-size:13px}
.filters input{flex:1 1 200px;min-width:160px}
.filters .count{color:var(--muted);font-size:13px;margin-left:auto}
table{width:100%;border-collapse:collapse;font-size:13.5px}
th,td{padding:8px 10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
th{color:var(--muted);font-weight:600;font-size:12px;text-transform:uppercase;letter-spacing:.4px;cursor:pointer;user-select:none;white-space:nowrap}
th:hover{color:var(--text)}
th.num,td.num{text-align:right}
tbody tr{cursor:pointer}
tbody tr:hover{background:var(--panel2)}
td .cat{display:block;font-size:12px;color:var(--muted)}
td .slug{color:var(--dim);font-size:12px}
.badge{display:inline-block;border-radius:5px;padding:2px 8px;font-size:12px;font-weight:650;letter-spacing:.3px}
.badge.FARM{background:#173b2a;color:#7fd6a4}
.badge.THIN{background:#3d2f14;color:#e8c478}
.badge.SKIP{background:#26292f;color:#9a978c}
.wl{font-size:11px;color:var(--amber);border:1px solid #4a3d22;border-radius:4px;padding:0 5px;margin-left:6px;white-space:nowrap}
.mech{font-size:11px;color:var(--blue);border:1px solid #2b3d4d;border-radius:4px;padding:0 5px;margin-left:6px;white-space:nowrap}
.mapwrap{overflow:hidden}
.mapwrap svg{display:block;width:100%;height:auto}
.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:12.5px;color:var(--muted);margin:6px 0 0}
.legend i{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:5px}
.detail{position:fixed;inset:0;background:rgba(4,5,7,.72);display:flex;justify-content:flex-end;z-index:20}
.detail .sheet{background:var(--bg);width:min(760px,96vw);height:100%;overflow-y:auto;padding:22px 24px 40px;border-left:1px solid var(--line)}
.detail h2{font-size:20px;margin:0 0 2px}
.detail .meta{color:var(--muted);font-size:13px;margin:0 0 14px}
.detail .close{float:right;background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:6px;padding:6px 12px;cursor:pointer;font:inherit}
.kv{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px;margin:12px 0}
.kv>div{background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:8px 10px}
.kv .k{font-size:11.5px;color:var(--muted);text-transform:uppercase;letter-spacing:.4px}
.kv .v{font-size:16px;font-weight:650;margin-top:2px}
.kv .v small{font-size:12px;color:var(--muted);font-weight:400}
.formula{background:var(--panel);border:1px solid var(--line);border-left:3px solid var(--amber);border-radius:6px;padding:10px 12px;font-size:13.5px;margin:10px 0;line-height:1.6}
.wf{display:flex;align-items:stretch;gap:0;margin:12px 0;flex-wrap:wrap}
.wf .step{flex:1;min-width:110px;background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:8px 10px;margin-right:6px}
.wf .step .op{font-size:11.5px;color:var(--muted)}
.wf .step .val{font-size:15px;font-weight:650}
.wf .step .lab{font-size:12px;color:var(--muted)}
.wf .arr{align-self:center;color:var(--dim);margin-right:6px;font-size:18px}
.steps{margin:8px 0 0;padding:0;list-style:none}
.steps li{border-bottom:1px solid var(--line);padding:9px 2px;font-size:13.5px}
.steps li b{color:var(--amber)}
.steps .st-cost{color:var(--muted);font-size:12.5px}
.verdictbox{border-radius:8px;padding:12px 14px;margin:12px 0;font-size:13.5px}
.verdictbox.FARM{background:#12291c;border:1px solid #235c3d}
.verdictbox.THIN{background:#2b2110;border:1px solid #6b5518}
.verdictbox.SKIP{background:#1a1c20;border:1px solid var(--line)}
.verdictbox .net{font-size:18px;font-weight:700}
.warn{background:#2b1610;border:1px solid #6b2d1d;color:#f0b09a;border-radius:6px;padding:10px 12px;margin:12px 0}
table.plain td,table.plain th{cursor:default}
table.plain tbody tr{cursor:default}
table.plain tbody tr:hover{background:none}
footer{color:var(--dim);font-size:12.5px;margin-top:18px;line-height:1.6}
footer b{color:var(--muted)}
@media (max-width:760px){.wrap{padding:14px 12px 30px}th:nth-child(4),td:nth-child(4){display:none}}
/* Round 5: P25-POSITIVE tier, formula box, best-per-hour callout, board summary */
.badge.P25P{background:#0a4d33;color:#4de8b0}
.verdictbox.P25P{background:#0c2b1f;border:1px solid #1f7a54}
/* Round 6 fixes: P25-FULL marker for the rows that still break even at p25
   fully costed, and the small inline fully-costed p25 line beside the badge. */
.badge.P25FULL{background:#0a3d2e;color:#7fd6a4;border:1px solid #2fd6a3}
.p25full{display:block;font-size:11px;color:var(--muted);margin-top:2px;line-height:1.35}
.feesplit{display:block;font-size:11px;color:var(--muted);margin-top:2px;line-height:1.35}
.formulabox{border-left:3px solid var(--amber)}
.formulabox h2{color:var(--amber)}
.bigformula{font-size:17px;font-weight:650;margin:8px 0}
.callout{border-color:#4a3d22}
.callout h2{color:var(--amber)}
.callout .bignum{font-size:20px;font-weight:700;color:var(--amber)}
.bandstrip p{margin:4px 0}
.fine{font-size:12.5px;color:var(--muted)}
table.plain th[data-sort]{cursor:pointer}
```

